#!/usr/bin/env bash\nset -e\n\n# Test fix keyword\noutput=$(echo "Fix bug in parser" | ./src/enrich.sh)\nexpected="Fix bug in parser 🐛"\nif [[ "$output" != "$expected" ]]; then\n  echo "FAIL: expected '$expected', got '$output'"\n  exit 1\nfi\n\n# Test add keyword\noutput=$(echo "Add new feature" | ./src/enrich.sh)\nexpected="Add new feature ✨"\nif [[ "$output" != "$expected" ]]; then\n  echo "FAIL: expected '$expected', got '$output'"\n  exit 1\nfi\n\n# Test docs keyword\noutput=$(echo "Update docs for API" | ./src/enrich.sh)\nexpected="Update docs for API 📚"\nif [[ "$output" != "$expected" ]]; then\n  echo "FAIL: expected '$expected', got '$output'"\n  exit 1\nfi\n\n# Test default case\noutput=$(echo "Refactor codebase" | ./src/enrich.sh)\nexpected="Refactor codebase 🎉"\nif [[ "$output" != "$expected" ]]; then\n  echo "FAIL: expected '$expected', got '$output'"\n  exit 1\nfi\n\necho "All tests passed."
